//! Parity test: the Rust binary must reproduce the TS engine's output exactly.
//!
//! The golden snapshot (`golden.json`) was generated by running a battery of
//! queries through the TS engine (`@manobu/japanese`) before it was deleted.
//! Each battery key maps to one MCP tool call here; the tool's JSON text
//! output is compared semantically (after dropping the tool-layer `description`
//! field that the golden engine calls never had).
//!
//! Regenerate a stale key only when the *data contract* intentionally changed
//! (Rust being wrong is fixed in Rust, not here):
//!   cargo build --manifest-path crates/jlpt-mcp/Cargo.toml
//!   bun scripts/parity-golden.ts <key> <tool> <json-args>
//! It prints the before/after and rewrites that one key. `search_vocab_english`
//! was refreshed this way after TASK-23.4-era JMdict widening put 作る ("cr**eat**e
//! (an artistic work)") ahead of 食べる in the ASCII substring scan.
//!
//! TASK-23.1: when the optional `vaporetto` feature is active, Japanese query
//! results for `search_*` are reranked by matched-token-count (the in-process
//! analogue of `vaporetto_or_query` + `bm25()`). That keeps the hit-set the
//! same as the TS engine's substring scan — so golden membership is compared
//! by content-key, and rank is only relaxed for Japanese queries.

use std::collections::HashSet;
use std::io::{BufRead, Write};

use serde_json::{json, Value};

struct McpClient {
    child: std::process::Child,
    stdin: std::process::ChildStdin,
    stdout: std::io::BufReader<std::process::ChildStdout>,
    next_id: u64,
}

impl McpClient {
    fn spawn() -> Self {
        Self::spawn_with_env(&[])
    }

    /// TASK-93: tests that drive the `JLPT_MCP_DEBUG=1`-gated debug tools spawn
    /// the sidecar with the flag; everything else stays on the default surface.
    fn spawn_with_env(vars: &[(&str, &str)]) -> Self {
        let mut child = std::process::Command::new(env!("CARGO_BIN_EXE_jlpt-mcp"))
            .envs(vars.iter().map(|(name, value)| (*name, *value)))
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .spawn()
            .expect("spawn jlpt-mcp");
        let stdin = child.stdin.take().expect("stdin");
        let stdout = std::io::BufReader::new(child.stdout.take().expect("stdout"));
        Self {
            child,
            stdin,
            stdout,
            next_id: 0,
        }
    }

    /// One request, answered with the full response frame so a caller can
    /// assert on `error` as well as `result`.
    fn frame(&mut self, method: &str, params: Value) -> Value {
        self.next_id += 1;
        let id = self.next_id;
        let msg = json!({
            "jsonrpc": "2.0",
            "id": id,
            "method": method,
            "params": params,
        });
        self.stdin
            .write_all(serde_json::to_string(&msg).unwrap().as_bytes())
            .unwrap();
        self.stdin.write_all(b"\n").unwrap();
        self.stdin.flush().unwrap();

        loop {
            let mut line = String::new();
            let bytes = self.stdout.read_line(&mut line).expect("read rpc response");
            if bytes == 0 {
                // Child died (startup panic, missing corpus…) — fail loudly
                // instead of looping on EOF forever.
                let status = self.child.wait().expect("wait for child");
                panic!("jlpt-mcp exited before responding ({status})");
            }
            if line.trim().is_empty() {
                continue;
            }
            let resp: Value = serde_json::from_str(&line).expect("valid jsonrpc line");
            if resp.get("id").and_then(Value::as_u64) == Some(id) {
                return resp;
            }
        }
    }

    fn rpc(&mut self, method: &str, params: Value) -> Value {
        let response = self.frame(method, params);
        if let Some(err) = response.get("error") {
            panic!("rpc error on {method}: {err}");
        }
        response.get("result").cloned().expect("result")
    }

    fn notify(&mut self, method: &str, params: Value) {
        let msg = json!({
            "jsonrpc": "2.0",
            "method": method,
            "params": params,
        });
        self.stdin
            .write_all(serde_json::to_string(&msg).unwrap().as_bytes())
            .unwrap();
        self.stdin.write_all(b"\n").unwrap();
        self.stdin.flush().unwrap();
    }

    fn tool_text(&mut self, name: &str, args: Value) -> Value {
        let result = self.rpc("tools/call", json!({ "name": name, "arguments": args }));
        let content = result
            .get("content")
            .and_then(Value::as_array)
            .expect("content array");
        let text = content
            .iter()
            .find(|c| c.get("type").and_then(Value::as_str) == Some("text"))
            .and_then(|c| c.get("text"))
            .and_then(Value::as_str)
            .expect("text content");
        serde_json::from_str(text).unwrap_or_else(|_| json!({ "__unparsed": text }))
    }
}

impl Drop for McpClient {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

/// TASK-93: the sidecar env that un-hides `vaporetto_split` / `vaporetto_warmup`.
const DEBUG: [(&str, &str); 1] = [("JLPT_MCP_DEBUG", "1")];

/// Handshake on a freshly spawned client so `tools/*` requests are answered.
fn handshake(client: &mut McpClient, name: &str) {
    client.rpc(
        "initialize",
        json!({
            "protocolVersion": "2025-11-25",
            "capabilities": {},
            "clientInfo": { "name": name, "version": "0" },
        }),
    );
    client.notify("notifications/initialized", json!({}));
}

/// Visible tool names, sorted (the router already sorts, this just keeps the
/// assertion independent of that).
fn tool_names(client: &mut McpClient) -> Vec<String> {
    let listed = client.rpc("tools/list", json!({}));
    let mut names: Vec<String> = listed["tools"]
        .as_array()
        .expect("tools array")
        .iter()
        .filter_map(|tool| tool["name"].as_str().map(str::to_string))
        .collect();
    names.sort();
    names
}

fn assert_no_keys(value: &Value, forbidden: &[&str]) {
    if let Some(object) = value.as_object() {
        for key in object.keys() {
            assert!(
                !forbidden.contains(&key.as_str()),
                "unexpected answer key field {key}"
            );
            assert_no_keys(&object[key], forbidden);
        }
    } else if let Some(array) = value.as_array() {
        for entry in array {
            assert_no_keys(entry, forbidden);
        }
    }
}

/// TASK-93 AC#1: the debug tools are absent from the default surface and
/// present under `JLPT_MCP_DEBUG=1`, and a direct call on a hidden tool is
/// rejected rather than silently served.
#[test]
fn debug_tools_are_gated_by_the_env_flag() {
    let mut default_client = McpClient::spawn();
    handshake(&mut default_client, "gating-default");
    let hidden = [
        "vaporetto_split".to_string(),
        "vaporetto_warmup".to_string(),
    ];
    let surface = tool_names(&mut default_client);
    for name in &hidden {
        assert!(
            !surface.contains(name),
            "debug tool {name} must not be listed without the flag; got {surface:?}"
        );
    }
    assert!(
        surface.contains(&"lookup_vocab".to_string()),
        "corpus tools must stay listed; got {surface:?}"
    );
    assert!(
        surface.contains(&"drill_candidates".to_string()),
        "drill_candidates must be public; got {surface:?}"
    );
    assert_eq!(
        surface.len(),
        17,
        "unexpected default tool surface: {surface:?}"
    );
    let rejected = default_client.frame(
        "tools/call",
        json!({ "name": "vaporetto_warmup", "arguments": {} }),
    );
    assert_eq!(
        rejected["error"]["message"].as_str(),
        Some("tool not found"),
        "a hidden debug tool must be rejected; got {rejected}"
    );

    let mut debug_client = McpClient::spawn_with_env(&DEBUG);
    handshake(&mut debug_client, "gating-debug");
    let debug_surface = tool_names(&mut debug_client);
    for name in &hidden {
        assert!(
            debug_surface.contains(name),
            "debug tool {name} must be listed with JLPT_MCP_DEBUG=1; got {debug_surface:?}"
        );
    }
    assert!(
        debug_surface.contains(&"drill_candidates".to_string()),
        "drill_candidates must stay public in debug mode; got {debug_surface:?}"
    );
    assert_eq!(
        debug_surface.len(),
        surface.len() + hidden.len(),
        "the flag must add exactly the debug tools"
    );
    assert_eq!(debug_surface.len(), 19);
}

#[test]
fn drill_candidates_is_public_deterministic_and_key_free() {
    let mut client = McpClient::spawn();
    handshake(&mut client, "drill-candidates");
    let request = json!({
        "level": "N5",
        "source": "vocab",
        "limit": 5,
        "seed": "task-123:batch-0"
    });
    let first = client.tool_text("drill_candidates", request.clone());
    let second = client.tool_text("drill_candidates", request);
    assert_eq!(
        first, second,
        "the same seed must return the same candidates"
    );
    assert_eq!(first["level"], "N5");
    assert_eq!(first["seed"], "task-123:batch-0");

    let candidates = first["candidates"].as_array().expect("candidate array");
    assert!(!candidates.is_empty());
    assert!(candidates.len() <= 5);
    let anchors: Vec<&str> = candidates
        .iter()
        .filter_map(|candidate| candidate["anchors"][0].as_str())
        .collect();
    assert_eq!(
        anchors,
        vec![
            "vocab:N5:村:むら",
            "vocab:N5:先週:せんしゅう",
            "vocab:N5:テスト:テスト",
            "vocab:N5:答える:こたえる",
            "vocab:N5:それ:それ",
        ]
    );
    for candidate in candidates {
        let anchors = candidate["anchors"].as_array().expect("anchor array");
        assert!(!anchors.is_empty());
        assert!(anchors.iter().all(|anchor| {
            anchor
                .as_str()
                .is_some_and(|value| value.starts_with("vocab:"))
        }));
        assert!(candidate["entry"].is_object());
        assert_no_keys(
            candidate,
            &["answerIndex", "correct", "fsrsVocabId", "options"],
        );
    }

    for source in ["grammar", "kanji", "sentence"] {
        let result = client.tool_text(
            "drill_candidates",
            json!({
                "level": "N5",
                "source": source,
                "limit": 2,
                "seed": "task-123:source-smoke"
            }),
        );
        assert!(
            !result["candidates"]
                .as_array()
                .expect("candidate array")
                .is_empty(),
            "{source} returned no candidates"
        );
    }
}

/// TASK-95: the advertised serverInfo must carry the package version rather
/// than a second literal that can outlive the next bump.
#[test]
fn initialize_advertises_the_package_version() {
    let mut client = McpClient::spawn();
    let result = client.rpc(
        "initialize",
        json!({
            "protocolVersion": "2025-11-25",
            "capabilities": {},
            "clientInfo": { "name": "version-test", "version": "0" },
        }),
    );
    assert_eq!(
        result["serverInfo"]["version"].as_str(),
        Some(env!("CARGO_PKG_VERSION")),
        "the sidecar must advertise its own Cargo.toml version"
    );
    assert_eq!(
        result["serverInfo"]["name"].as_str(),
        Some("jlpt-vocab"),
        "the handler name is part of the same contract; got {result}"
    );
}

/// TASK-55: the reading bridge must not displace the deinflected target —
/// みました returns 見る (not 〜む-family rows whose readings merely contain
/// み), and すむ-style mid-word matches stay out. Runs against the spawned
/// binary with the vaporetto feature + model (same env as parity).
#[test]
fn search_vocab_reading_bridge_ranks_target_first() {
    let mut client = McpClient::spawn();
    client.rpc(
        "initialize",
        json!({
            "protocolVersion": "2025-11-25",
            "capabilities": {},
            "clientInfo": { "name": "task55", "version": "0" }
        }),
    );
    client.notify("notifications/initialized", json!({}));

    let out = client.tool_text("search_vocab", json!({ "query": "みました", "limit": 10 }));
    let rows: Vec<Value> = out.as_array().cloned().unwrap_or_default();
    assert!(
        rows.iter()
            .any(|r| r.get("word").and_then(|w| w.as_str()) == Some("見る")),
        "みました must return 見る; got: {rows:?}"
    );
    let first_non_target_above = rows
        .iter()
        .take_while(|r| r.get("word").and_then(|w| w.as_str()) != Some("見る"))
        .filter_map(|r| r.get("reading").and_then(|x| x.as_str()))
        .all(|reading| reading.starts_with('み'));
    assert!(
        first_non_target_above,
        "rows above 見る must have み-prefixed readings; got: {rows:?}"
    );

    // Regression guard: the headline case stays first.
    let out = client.tool_text(
        "search_vocab",
        json!({ "query": "たべました", "limit": 10 }),
    );
    let rows: Vec<Value> = out.as_array().cloned().unwrap_or_default();
    assert_eq!(
        rows.first()
            .and_then(|r| r.get("word"))
            .and_then(|w| w.as_str()),
        Some("食べる"),
        "たべました must return 食べる first; got: {rows:?}"
    );
}

#[test]
fn parity_with_ts_engine() {
    let golden: Value =
        serde_json::from_str(include_str!("golden.json")).expect("golden.json parses");
    let golden = golden.as_object().expect("golden is an object");

    let mut client = McpClient::spawn();
    client.rpc(
        "initialize",
        json!({
            "protocolVersion": "2025-11-25",
            "capabilities": {},
            "clientInfo": { "name": "parity-test", "version": "0" },
        }),
    );
    client.notify("notifications/initialized", json!({}));

    // key → (tool, args, post-process, compare_mode)
    let battery: Vec<(&str, &str, Value, Option<u64>, bool, &str)> = vec![
        (
            "lookup_vocab_kanji",
            "lookup_vocab",
            json!({"word": "食べる"}),
            None,
            false,
            "exact",
        ),
        (
            "lookup_vocab_kana",
            "lookup_vocab",
            json!({"word": "たべる"}),
            None,
            false,
            "exact",
        ),
        (
            "lookup_vocab_miss",
            "lookup_vocab",
            json!({"word": "zzzz不存在"}),
            None,
            false,
            "exact",
        ),
        (
            "search_vocab_english",
            "search_vocab",
            json!({"query": "eat", "limit": 5}),
            None,
            false,
            "exact",
        ),
        (
            "search_vocab_kana",
            "search_vocab",
            json!({"query": "たべ", "limit": 5}),
            None,
            false,
            "exact",
        ),
        (
            "search_vocab_none",
            "search_vocab",
            json!({"query": "qqqq", "limit": 3}),
            None,
            false,
            "exact",
        ),
        (
            "list_vocab_n5_head",
            "list_vocab_by_level",
            json!({"level": "N5"}),
            Some(3),
            false,
            "exact",
        ),
        (
            "lookup_grammar",
            "lookup_grammar",
            json!({"id": "te-form-basic"}),
            None,
            false,
            "exact",
        ),
        (
            "lookup_grammar_miss",
            "lookup_grammar",
            json!({"id": "no-such-id"}),
            None,
            false,
            "exact",
        ),
        (
            "search_grammar",
            "search_grammar",
            json!({"query": "te-form", "limit": 5}),
            None,
            false,
            "exact",
        ),
        (
            "search_grammar_en",
            "search_grammar",
            json!({"query": "conditional", "limit": 3}),
            None,
            false,
            "exact",
        ),
        (
            "list_grammar_n4_head",
            "list_grammar_by_level",
            json!({"level": "N4"}),
            Some(2),
            false,
            "exact",
        ),
        (
            "conjugate_ichidan",
            "conjugate_verb",
            json!({"word": "食べる"}),
            None,
            false,
            "exact",
        ),
        (
            "conjugate_kana",
            "conjugate_verb",
            json!({"word": "たべる"}),
            None,
            false,
            "exact",
        ),
        (
            "conjugate_godan",
            "conjugate_verb",
            json!({"word": "行く"}),
            None,
            false,
            "exact",
        ),
        (
            "conjugate_adjective",
            "conjugate_verb",
            json!({"word": "高い"}),
            None,
            false,
            "exact",
        ),
        (
            "conjugate_miss",
            "conjugate_verb",
            json!({"word": "not-a-word"}),
            None,
            false,
            "exact",
        ),
        (
            "lookup_kanji",
            "lookup_kanji",
            json!({"character": "食"}),
            None,
            false,
            "exact",
        ),
        (
            "lookup_kanji_miss",
            "lookup_kanji",
            json!({"character": "龘"}),
            None,
            false,
            "exact",
        ),
        (
            "search_kanji_meaning",
            "search_kanji",
            json!({"query": "eat", "limit": 5}),
            None,
            false,
            "exact",
        ),
        (
            "search_kanji_kun",
            "search_kanji",
            json!({"query": "たべ", "limit": 5}),
            None,
            false,
            "exact",
        ),
        (
            "list_kanji_n5_head",
            "list_kanji_by_level",
            json!({"level": "N5"}),
            Some(3),
            false,
            "exact",
        ),
        // pitch lookups: drop the tool-layer `description` before comparing
        (
            "lookup_pitch_hashi",
            "lookup_pitch_accent",
            json!({"word": "はし"}),
            None,
            true,
            "exact",
        ),
        (
            "lookup_pitch_kanji",
            "lookup_pitch_accent",
            json!({"word": "橋"}),
            None,
            true,
            "exact",
        ),
        (
            "lookup_pitch_miss",
            "lookup_pitch_accent",
            json!({"word": "わからなーい"}),
            None,
            true,
            "exact",
        ),
        (
            "search_pitch",
            "search_pitch_accent",
            json!({"query": "はし", "limit": 5}),
            None,
            false,
            "kana_order",
        ),
        (
            "empty_vocab_search",
            "search_vocab",
            json!({"query": "  ", "limit": 5}),
            None,
            false,
            "exact",
        ),
        (
            "empty_kanji_lookup",
            "lookup_kanji",
            json!({"character": ""}),
            None,
            false,
            "exact",
        ),
    ];

    let mut failures = 0;
    for (key, tool, args, slice, strip_desc, cmp) in battery.iter() {
        let mut actual = client.tool_text(tool, args.clone());
        if let Some(n) = slice {
            if let Some(arr) = actual.as_array_mut() {
                arr.truncate(*n as usize);
            }
        }
        if *strip_desc {
            if let Some(arr) = actual.as_array_mut() {
                for entry in arr {
                    if let Some(obj) = entry.as_object_mut() {
                        obj.remove("description");
                    }
                }
            }
        }
        let key_owned: String = (*key).to_string();
        let expected = golden
            .get(key_owned.as_str())
            .cloned()
            .unwrap_or(Value::Null);
        let ok: bool = match *cmp {
            "kana_order" => compare_pitch_search(&actual, &expected),
            _ => actual == expected,
        };
        eprintln!("  result {} ({cmp} key={})", ok, key_owned);
        if !ok {
            failures += 1;
            eprintln!(
                "✗ {key}: MISMATCH ({cmp})\n  rust: {}\n  ts:   {}",
                serde_json::to_string(&actual).unwrap_or_default(),
                serde_json::to_string(&expected).unwrap_or_default()
            );
        }
    }

    // describe_pitch strings (golden values are the TS engine's description arrays)
    let describe_checks: Vec<(&str, &str, Value)> = vec![
        (
            "describe_pitch_hashi",
            "lookup_pitch_accent",
            json!({"word": "はし"}),
        ),
        (
            "describe_pitch_udon",
            "lookup_pitch_accent",
            json!({"word": "うどん"}),
        ),
    ];
    for (key, tool, args) in describe_checks {
        let actual = client.tool_text(tool, args);
        let descriptions: Vec<Value> = actual
            .as_array()
            .expect("pitch array")
            .iter()
            .map(|e| e.get("description").cloned().unwrap_or(Value::Null))
            .collect();
        let expected = golden.get(key).cloned().unwrap_or(Value::Null);
        if Value::Array(descriptions) != expected {
            failures += 1;
            eprintln!("✗ {key}: description mismatch");
        }
    }

    eprintln!("golden table:");
    for (k, v) in golden.iter() {
        let first = v
            .as_array()
            .and_then(|a| a.first())
            .map(|x| serde_json::to_string(x).unwrap_or_default())
            .unwrap_or_default();
        eprintln!("  {}: {}", k, first);
    }

    if failures > 0 {
        eprintln!("{failures} parity check(s) failed");
        panic!("{failures} parity check(s) failed");
    }
    eprintln!("✓ all parity checks passed");
}

/// Stable sort key for pitch entries so the 23.1 rerank is compared by
/// membership, not by JSON order.
fn pitch_key(o: &serde_json::Map<String, Value>) -> (String, String) {
    let word = o
        .get("word")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or_default();
    let reading = o
        .get("reading")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or_default();
    (word, reading)
}

fn compare_pitch_search(actual: &Value, expected: &Value) -> bool {
    let a: Vec<_> = actual
        .as_array()
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .filter_map(|v| v.as_object().cloned())
        .collect();
    let e: Vec<_> = expected
        .as_array()
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .filter_map(|v| v.as_object().cloned())
        .collect();
    if a.len() != e.len() {
        return false;
    }
    let ae_set: HashSet<_> = a.iter().map(|o| pitch_key(o)).collect();
    let ee_set: HashSet<_> = e.iter().map(|o| pitch_key(o)).collect();
    ae_set == ee_set
}

/// TASK-23.26 AC#4 (behavioral, not golden-backed): a kana-reading query the
/// corpus can never substring-match (食べる's stored reading is たべ, the
/// query uses the model's katakana reading タベ + る) must still surface the
/// 食べる entry through the tag channel. Only meaningful when the model is
/// actually loaded — on whitespace-fallback builds the query degrades to the
/// legacy substring scan and the assertion would fail there, so skip.
#[test]
fn search_vocab_matches_inflected_kana_reading_via_tags() {
    let mut client = McpClient::spawn_with_env(&DEBUG);
    client.rpc(
        "initialize",
        json!({
            "protocolVersion": "2025-11-25",
            "capabilities": {},
            "clientInfo": { "name": "parity-test", "version": "0" },
        }),
    );
    client.notify("notifications/initialized", json!({}));
    let active = client.tool_text("vaporetto_split", json!({"text": "たべました"}));
    if active
        .get("model_active")
        .and_then(|v| v.as_bool())
        .map(|active| !active)
        .unwrap_or(true)
    {
        eprintln!("model not active — skipping tag-channel test");
        return;
    }
    // たべました (not タベる — the model emits one untagged token for
    // mixed-script katakana queries, a doc-8 probe fact recorded in the
    // engine test comment): stem reading タベ→たべ prefix-matches the
    // corpus reading たべる.
    let results = client.tool_text("search_vocab", json!({"query": "たべました", "limit": 10}));
    let entries = results.as_array().expect("search_vocab returns an array");
    assert!(
        entries
            .iter()
            .any(|e| e.get("word").and_then(|w| w.as_str()) == Some("食べる")),
        "たべました must reach the 食べる entry via the reading tag channel; got: {entries:?}"
    );
}

/// TASK-24.1 AC#2: the warmup tool loads the predictor once and reports
/// elapsed ms. Cold + warm covered here — the cold call must report
/// `warmed: true` (model present in this repo) and a warm re-call must
/// report a near-zero second load (OnceLock hit). Byte-output of every
/// other tool is untouched (warmup reads no corpus state), so the
/// parity-golden policy holds.
#[test]
fn vaporetto_warmup_reports_load_once() {
    let mut client = McpClient::spawn_with_env(&DEBUG);
    client.rpc(
        "initialize",
        json!({
            "protocolVersion": "2025-11-25",
            "capabilities": {},
            "clientInfo": { "name": "warmup-test", "version": "0" },
        }),
    );
    client.notify("notifications/initialized", json!({}));

    let first = client.tool_text("vaporetto_warmup", json!({}));
    if first
        .get("model_active")
        .and_then(Value::as_bool)
        .map(|a| !a)
        .unwrap_or(true)
    {
        eprintln!("model not active — skipping warmup timing test");
        return;
    }
    assert_eq!(
        first.get("warmed").and_then(Value::as_bool),
        Some(true),
        "cold warmup must report warmed=true; got {first}"
    );
    assert!(
        first.get("elapsed_ms").and_then(Value::as_u64).is_some(),
        "cold warmup must report elapsed_ms; got {first}"
    );

    // Warm re-call: predictor already in the OnceLock — the second load
    // must be ~0 (not re-decode).
    let second = client.tool_text("vaporetto_warmup", json!({}));
    assert_eq!(
        second.get("warmed").and_then(Value::as_bool),
        Some(true),
        "warm re-call must stay warmed=true; got {second}"
    );
    let again = second
        .get("elapsed_ms")
        .and_then(Value::as_u64)
        .expect("elapsed_ms on warm re-call");
    assert!(
        again < 100,
        "warm re-call must be a OnceLock hit (<100 ms), got {again} ms"
    );
}
